use crate::aap::caps::inference_llm;

struct Node;

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Assemble the material for the model from the kept entries only.
        let mut material = String::new();
        for e in &selected.entries {
            if e.kept {
                material.push_str(&e.title);
                material.push_str(" — ");
                material.push_str(&e.summary);
                material.push('\n');
            }
        }

        let system = "You write the overview for a daily feed digest. \
                      Summarise the day's kept items in at most 600 characters. \
                      Return prose only, no preamble.";
        let prompt = format!("Date: {}\n\nItems:\n{}", info.date, material);

        // The node's entire authority: one inference call, no tools.
        let mut overview = inference_llm::infer(system, &prompt, "digest");

        // ensures len(overview) <= 600, counted in characters (Python `len`).
        // Truncate on a char boundary so we never exceed the bound.
        if overview.chars().count() > 600 {
            overview = overview.chars().take(600).collect();
        }

        // ensures len(date) == 10: discharged by `requires len(info.date) == 10`,
        // so the input date is passed through unchanged.
        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
